@Test
public void testScheduleAtFixedRate() {
    Runnable task = mock(Runnable.class);
    doNothing().when(task).run();
    executor.scheduleAtFixedRate(task, 5, 10, TimeUnit.MILLISECONDS);
    // first delay
    mockExecutorControl.advance(Duration.ofMillis(2));
