public void testWatchIsCancelledOnTimeout() throws Exception {
    Request request = Request.newBuilder().setHeader(BKPacketHeader.newBuilder().setTxnId(System.currentTimeMillis()).setVersion(ProtocolVersion.VERSION_THREE).setOperation(OperationType.READ_ENTRY).build()).setReadRequest(ReadRequest.newBuilder().setLedgerId(10).setEntryId(1).setMasterKey(ByteString.copyFrom(new byte[0])).setPreviousLAC(0).setTimeOut(1).build()).build();
    Channel channel = mock(Channel.class);
    Bookie bookie = mock(Bookie.class);
    BookieRequestProcessor requestProcessor = mock(BookieRequestProcessor.class);
    when(requestProcessor.getBookie()).thenReturn(bookie);
    when(requestProcessor.getRequestStats()).thenReturn(new RequestStats(NullStatsLogger.INSTANCE));
    when(bookie.waitForLastAddConfirmedUpdate(anyLong(), anyLong(), any())).thenReturn(true);
    when(bookie.readEntry(anyLong(), anyLong())).thenReturn(Unpooled.buffer());
    when(bookie.readLastAddConfirmed(anyLong())).thenReturn(Long.valueOf(1));
    CompletableFuture<Void> cancelFuture = new CompletableFuture<>();
    doAnswer(invocationOnMock -> {
        cancelFuture.complete(null);
        return null;
    }).when(bookie).cancelWaitForLastAddConfirmedUpdate(anyLong(), any());
    LongPollReadEntryProcessorV3 processor = new LongPollReadEntryProcessorV3(request, channel, requestProcessor, executor, executor, timer);
    processor.run();
    cancelFuture.get(10, TimeUnit.SECONDS);
}

