    when(channel.writeAndFlush(any())).thenReturn(mock(ChannelPromise.class));
    doAnswer(invocationOnMock -> {
        WriteCallback wc = invocationOnMock.getArgument(2);
        wc.writeComplete(0, request.getAddRequest().getLedgerId(), request.getAddRequest().getEntryId(), null, null);
        return null;
    }).when(bookie).addEntry(any(ByteBuf.class), eq(false), any(WriteCallback.class), same(channel), eq(new byte[0]));
