private void testShadeLedgerManagerFactoryAllowed(String factoryClassName, boolean allowShaded) throws Exception {
    ServerConfiguration conf = new ServerConfiguration();
    conf.setAllowShadedLedgerManagerFactoryClass(allowShaded);
    conf.setLedgerManagerFactoryClassName(factoryClassName);
    LayoutManager manager = mock(LayoutManager.class);
    LedgerLayout layout = new LedgerLayout("org.apache.bookkeeper.meta.HierarchicalLedgerManagerFactory", HierarchicalLedgerManagerFactory.CUR_VERSION);
    when(manager.readLedgerLayout()).thenReturn(layout);
    LedgerManagerFactory factory = mock(LedgerManagerFactory.class);
    when(factory.initialize(any(AbstractConfiguration.class), same(manager), anyInt())).thenReturn(factory);
    PowerMockito.mockStatic(ReflectionUtils.class);
    when(ReflectionUtils.newInstance(any(Class.class))).thenReturn(factory);
    try {
        LedgerManagerFactory result = AbstractZkLedgerManagerFactory.newLedgerManagerFactory(conf, manager);
        if (allowShaded) {
            assertSame(factory, result);
            verify(factory, times(1)).initialize(any(AbstractConfiguration.class), same(manager), anyInt());
        } else {
            fail("Should fail to instantiate ledger manager factory if allowShaded is false");
        }
    } catch (IOException ioe) {
        if (allowShaded) {
            fail("Should not fail to instantiate ledger manager factory is allowShaded is true");
        } else {
            assertTrue(ioe.getCause() instanceof ClassNotFoundException);
        }
    }
}

